-- =============================================================================
-- 0042_karta_vocabulary.sql
--
-- GENERATED by scripts/build-karta-vocabulary.mjs. Do not hand-edit.
--
-- Say karta, not "the performer". It is the ordinary word for the one
-- performing a rite -- the karta of a shraddha, the karta of the household --
-- and every reader who opens this app already has it; "the performer" was a
-- translation of a term they had, and it described the rite from outside it.
--
-- The BOOK never names the performer at all. The only kart- forms in its 125
-- pages are sRSTikartrE and svayamkartrE, both the dative of kartR used as an
-- epithet of the DEITY. So this is the project choosing a word the tradition
-- uses, not quoting one the source supplied.
--
-- karta is the MASCULINE nominative of kartR; the feminine is kartrI, and a
-- husband and wife acting as one are the dampati. The UI inflects accordingly,
-- because the karta toggle knows who is sitting there. This prose does not:
-- these five sentences are about whoever is performing, not a named person, so
-- they take the bare role noun the way English takes "the cook". It is also
-- why the one gendered pronoun goes out with the noun -- "what HE is about to
-- become" was about a man, and nothing else here is.
--
-- Five strings across seven rows -- the purvangam is shared, so the Anga
-- Vandanam paragraph is on three poojas, and the two Asana Pooja strings are
-- the instruction and the philosophy of the SAME step on two poojas, which is
-- four mentions on two rows. Matched on the FULL current text, not a regex: a
-- blind replace on a text column is how you find out afterwards that it also
-- rewrote something you had not read.
--
-- NOT touched: two steps say a household vidhi "expects to be performed by
-- real households". That is the ordinary verb, not the noun, and rewriting it
-- would be a grammar error rather than a vocabulary correction.
--
-- One pronoun goes with the noun. The Asana Pooja philosophy said the seat is
-- consecrated "because that is what HE is about to become". Nothing in the step
-- is about a man; it describes whoever is sitting down. It now says they.
--
-- Idempotent: a row already carrying the new text matches nothing and is left.
-- =============================================================================

begin;

-- Anga Vandanam (philosophy_en)
update public.pooja_steps set philosophy_en = 'Twelve names of Vishnu touched to twelve places, and again they are the same twelve in any Smartha pooja whichever god it is for. The body is being named part by part before it is asked to do anything. Nothing has been offered yet and no deity has been invited; this is still the karta getting ready.', updated_at = now()
 where philosophy_en = 'Twelve names of Vishnu touched to twelve places, and again they are the same twelve in any Smartha pooja whichever god it is for. The body is being named part by part before it is asked to do anything. Nothing has been offered yet and no deity has been invited; this is still the performer getting ready.';

-- Asana Pooja (philosophy_en)
update public.pooja_steps set philosophy_en = 'You consecrate the seat while sitting outside it, and only then take your place. Every other upachara in the pooja is offered to someone else. This one is offered to the ground under yourself, and it is asked of the earth rather than of a god — bear me, and make this seat pure. The karta is prepared like an object in the rite, because that is what they are about to become.', updated_at = now()
 where philosophy_en = 'You consecrate the seat while sitting outside it, and only then take your place. Every other upachara in the pooja is offered to someone else. This one is offered to the ground under yourself, and it is asked of the earth rather than of a god — bear me, and make this seat pure. The performer is prepared like an object in the rite, because that is what he is about to become.';

-- Asana Pooja (instruction_en)
update public.pooja_steps set instruction_en = 'Sprinkle a little water on your seat while reciting this, sitting OUTSIDE the seat. Then take your place on it. The seat is consecrated before the karta occupies it, not after.', updated_at = now()
 where instruction_en = 'Sprinkle a little water on your seat while reciting this, sitting OUTSIDE the seat. Then take your place on it. The seat is consecrated before the performer occupies it, not after.';

-- Kshama Prarthana & Conclusion (philosophy_en)
update public.pooja_steps set philosophy_en = 'Yat pujitam maya deva paripurnam tad astu te: whatever I have worshipped, let it stand complete FOR YOU. Not "forgive me" and not "I did my best". Completion is asked for as something the deity grants, not something the karta achieved, which is why the verse can concede mantra, rite and devotion all at once and still end the pooja properly.', updated_at = now()
 where philosophy_en = 'Yat pujitam maya deva paripurnam tad astu te: whatever I have worshipped, let it stand complete FOR YOU. Not "forgive me" and not "I did my best". Completion is asked for as something the deity grants, not something the performer achieved, which is why the verse can concede mantra, rite and devotion all at once and still end the pooja properly.';

-- Teertham (philosophy_en)
update public.pooja_steps set philosophy_en = 'Both rubrics here are about everyone else in the room: the conch water is sprinkled on all present INCLUDING oneself, and the teertham is given to all the other members of the household. The rest of this app is written for a single karta; this step is not.', updated_at = now()
 where philosophy_en = 'Both rubrics here are about everyone else in the room: the conch water is sprinkled on all present INCLUDING oneself, and the teertham is given to all the other members of the household. The rest of this app is written for a single performer; this step is not.';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- The noun is gone from every column a reader sees.
  select count(*) into n from public.pooja_steps
   where coalesce(instruction_en, '') ~* '\mperformer\M'
      or coalesce(meaning_en, '')     ~* '\mperformer\M'
      or coalesce(philosophy_en, '')  ~* '\mperformer\M';
  if n <> 0 then raise exception '% step(s) still say performer', n; end if;

  -- ...and the verb is still there, so this was a vocabulary change and not a
  -- regex that ate the word wherever it appeared.
  select count(*) into n from public.pooja_steps
   where coalesce(philosophy_en, '') like '%expects to be performed by real households%';
  if n < 1 then raise exception 'the ordinary verb "performed by" was destroyed too'; end if;

  -- The replacements landed rather than merely not-failing. Seven rows: the
  -- purvangam steps are shared between poojas, and Asana Pooja says it twice
  -- in one row, once in the instruction and once in the philosophy.
  select count(*) into n from public.pooja_steps
   where coalesce(instruction_en, '') ~* '\mkarta\M'
      or coalesce(philosophy_en, '')  ~* '\mkarta\M';
  if n <> 7 then raise exception 'expected 7 rows to say karta, found %', n; end if;

  -- The pronoun went with it.
  select count(*) into n from public.pooja_steps
   where coalesce(philosophy_en, '') like '%what he is about to become%';
  if n <> 0 then raise exception '% row(s) still say "what he is about to become"', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

